export const BOSS_NAMES = {
  5: 'GOLIATH',
  10: 'LEVIATHAN',
  15: 'OBLIVION',
  20: 'SINGULARITY',
};

export const ENEMY_ORDER = ['drone', 'runner', 'brute', 'shield', 'splitter'];

export function getFormStats(formId, level) {
  const form = FORMS[formId];
  const damageMult = 1 + 0.33 * (level - 1);
  const rateMult = 1 + 0.075 * (level - 1);
  const damage = form.damage * damageMult;
  const interval = form.interval / rateMult;
  const range = form.range + 11 * (level - 1);
  const chains = form.chains ? form.chains + Math.floor((level - 1) / 3) : 0;
  let dps = damage / interval;
  if (form.chains) {
    let chainMult = 1;
    for (let i = 0; i < chains - 1; i += 1) chainMult += form.falloff ** (i + 1);
    dps *= chainMult;
  }
  return {
    damage,
    interval,
    rate: 1 / interval,
    range,
    chains,
    dps,
    damageMult,
    rateMult,
    slow: form.slow ? Math.min(0.65, form.slow + (level - 1) * 0.012) : 0,
    burnDps: form.burnDps ? form.burnDps * damageMult : 0,
  };
}

export function upgradeCost(level) {
  if (level >= MAX_LEVEL) return null;
  return UPGRADE_COSTS[level - 1];
}

function hashSeed(seed, wave) {
  let h = (seed ^ Math.imul(wave + 1, 374761393)) >>> 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177) >>> 0;
  return (h ^ (h >>> 16)) >>> 0;
}

function mulberry32(a) {
  return function rand() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function pickWeighted(rng, pool) {
  let total = 0;
  for (const item of pool) total += item[1];
  let roll = rng() * total;
  for (const item of pool) {
    roll -= item[1];
    if (roll <= 0) return item[0];
  }
  return pool[pool.length - 1][0];
}

export function buildWave(wave, seed = 1337) {
  const rng = mulberry32(hashSeed(seed, wave));
  const boss = wave % 5 === 0;
  const baseCount = Math.min(28, 7 + Math.round(wave * 1.05));
  const count = boss ? Math.max(4, Math.round(baseCount * 0.78)) : baseCount;
  const pool = [['drone', 4.5]];
  if (wave >= 2) pool.push(['runner', Math.min(3, 1.5 + wave * 0.06)]);
  if (wave >= 3) pool.push(['brute', 1.2]);
  if (wave >= 4) pool.push(['shield', 0.9 + wave * 0.02]);
  if (wave >= 6) pool.push(['splitter', 0.85]);

  const entries = [];
  let at = 0;
  const baseInterval = Math.max(0.32, 0.6 - wave * 0.012);
  for (let i = 0; i < count; i += 1) {
    entries.push({ type: pickWeighted(rng, pool), at });
    at += baseInterval * (0.7 + rng() * 0.6);
  }

  const counts = {};
  for (const entry of entries) counts[entry.type] = (counts[entry.type] || 0) + 1;

  let bossHp = 0;
  if (boss) {
    bossHp = Math.round(900 * (1 + 0.22 * (wave - 5)));
    entries.push({ type: 'boss', at: at + 0.9 });
    counts.boss = 1;
  }

  return {
    wave,
    boss,
    bossHp,
    bossName: BOSS_NAMES[wave] || 'TITAN',
    entries,
    counts,
    total: entries.length,
    hpMul: 1 + 0.13 * (wave - 1) + 0.003 * (wave - 1) ** 2,
    goldMul: 1 + 0.04 * (wave - 1),
    bonus: 30 + wave * 12,
  };
}

export function describeComposition(counts) {
  return ENEMY_ORDER.filter((id) => counts[id]).map((id) => ({
    id,
    name: ENEMY_TYPES[id].name,
    count: counts[id],
    color: ENEMY_TYPES[id].color,
  }));
}

// Rounded, uniformly sampled enemy track.
// The path is built once and queried by distance for smooth movement.

function dist(a, b) {
  return Math.hypot(b.x - a.x, b.y - a.y);
}

function norm(a, b) {
  const d = dist(a, b) || 1;
  return { x: (b.x - a.x) / d, y: (b.y - a.y) / d };
}

export function buildPath(verts, cornerRadius = 54, step = 5) {
  const raw = [];
  const push = (p) => {
    const last = raw[raw.length - 1];
    if (!last || Math.hypot(p.x - last.x, p.y - last.y) > 0.001) raw.push(p);
  };

  const lineTo = (from, to) => {
    const length = dist(from, to);
    const n = Math.max(1, Math.ceil(length / step));
    for (let i = 1; i <= n; i += 1) {
      const t = i / n;
      push({ x: from.x + (to.x - from.x) * t, y: from.y + (to.y - from.y) * t });
    }
  };

  const quadTo = (a, c, b) => {
    const approx = dist(a, c) + dist(c, b);
    const n = Math.max(4, Math.ceil(approx / step));
    let prev = a;
    for (let i = 1; i <= n; i += 1) {
      const t = i / n;
      const it = 1 - t;
      const p = {
        x: it * it * a.x + 2 * it * t * c.x + t * t * b.x,
        y: it * it * a.y + 2 * it * t * c.y + t * t * b.y,
      };
      lineTo(prev, p);
      prev = p;
    }
  };

  push(verts[0]);
  for (let i = 1; i < verts.length - 1; i += 1) {
    const prev = verts[i - 1];
    const cur = verts[i];
    const next = verts[i + 1];
    const inDir = norm(prev, cur);
    const outDir = norm(cur, next);
    const r = Math.min(cornerRadius, dist(prev, cur) / 2, dist(cur, next) / 2);
    const p1 = { x: cur.x - inDir.x * r, y: cur.y - inDir.y * r };
    const p2 = { x: cur.x + outDir.x * r, y: cur.y + outDir.y * r };
    const end = raw[raw.length - 1];
    if (end) lineTo(end, p1);
    quadTo(p1, cur, p2);
  }
  const last = raw[raw.length - 1];
  const final = verts[verts.length - 1];
  if (last) lineTo(last, final);

  // Cumulative lengths.
  const points = [];
  const cumulative = [0];
  for (let i = 0; i < raw.length; i += 1) {
    const prev = raw[i - 1];
    if (prev) cumulative.push(cumulative[i - 1] + dist(prev, raw[i]));
    points.push(raw[i]);
  }

  const length = cumulative[cumulative.length - 1] || 1;

  function sample(distance) {
    const d = Math.max(0, Math.min(length, distance));
    let lo = 0;
    let hi = points.length - 1;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (cumulative[mid] <= d) lo = mid + 1;
      else hi = mid;
    }
    const i = Math.max(1, lo);
    const a = points[i - 1];
    const b = points[i] || points[i - 1];
    const seg = cumulative[i] - cumulative[i - 1] || 1;
    const t = (d - cumulative[i - 1]) / seg;
    return {
      x: a.x + (b.x - a.x) * t,
      y: a.y + (b.y - a.y) * t,
      angle: Math.atan2(b.y - a.y, b.x - a.x),
      distance: d,
    };
  }

  return { points, cumulative, length, sample };
}

// Tiny procedural sound engine. No external assets, no autoplay issues:
// the AudioContext is created on the first user gesture.

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.muted = false;
    this.gates = Object.create(null);
    this.noiseBuffer = null;
  }

  unlock() {
    if (!this.ctx) {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) return;
      this.ctx = new Ctx();
      this.master = this.ctx.createGain();
      this.master.gain.value = 0.6;
      this.master.connect(this.ctx.destination);
      this.noiseBuffer = this.makeNoise();
    }
    if (this.ctx.state === 'suspended') this.ctx.resume();
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.6, this.ctx.currentTime, 0.02);
    }
  }

  makeNoise() {
    const len = Math.floor(this.ctx.sampleRate * 0.4);
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i += 1) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  gate(key, ms) {
    if (!this.ctx) return false;
    const now = this.ctx.currentTime;
    if (this.gates[key] && (now - this.gates[key]) * 1000 < ms) return false;
    this.gates[key] = now;
    return true;
  }

  tone(freq, duration, opts = {}) {
    if (!this.ctx || this.muted) return;
    const {
      type = 'sine',
      volume = 0.06,
      slideTo = null,
      delay = 0,
      attack = 0.008,
    } = opts;
    const t0 = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (slideTo) {
      osc.frequency.exponentialRampToValueAtTime(Math.max(20, slideTo), t0 + duration);
    }
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.linearRampToValueAtTime(volume, t0 + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(t0);
    osc.stop(t0 + duration + 0.03);
  }

  noise(duration, opts = {}) {
    if (!this.ctx || this.muted) return;
    const {
      volume = 0.05,
      type = 'lowpass',
      frequency = 1200,
      slideTo = null,
      delay = 0,
    } = opts;
    const t0 = this.ctx.currentTime + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(frequency, t0);
    if (slideTo) filter.frequency.exponentialRampToValueAtTime(Math.max(40, slideTo), t0 + duration);
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.linearRampToValueAtTime(volume, t0 + 0.006);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    src.start(t0);
    src.stop(t0 + duration + 0.02);
  }

  ui() {
    if (!this.gate('ui', 40)) return;
    this.tone(520, 0.045, { type: 'square', volume: 0.018, slideTo: 760 });
  }

  upgrade() {
    const notes = [392, 523.25, 659.25, 783.99];
    notes.forEach((f, i) => this.tone(f, 0.2, { type: 'triangle', volume: 0.05, delay: i * 0.055 }));
    this.noise(0.25, { volume: 0.02, type: 'highpass', frequency: 2400 });
  }

  reforge() {
    this.noise(0.3, { volume: 0.05, type: 'bandpass', frequency: 500, slideTo: 3000 });
    [261.6, 392, 523.25].forEach((f, i) =>
      this.tone(f, 0.32, { type: 'sawtooth', volume: 0.028, delay: 0.05 + i * 0.04, slideTo: f * 1.5 }),
    );
  }

  waveStart(boss = false) {
    this.tone(boss ? 55 : 70, 0.5, { type: 'sawtooth', volume: 0.06, slideTo: boss ? 90 : 110 });
    this.noise(0.5, { volume: 0.03, type: 'lowpass', frequency: 400 });
    if (boss) {
      this.tone(110, 0.8, { type: 'square', volume: 0.035, delay: 0.15, slideTo: 82 });
    }
  }

  waveClear() {
    [523.25, 659.25, 783.99].forEach((f, i) =>
      this.tone(f, 0.24, { type: 'triangle', volume: 0.04, delay: i * 0.07 }),
    );
  }

  shoot(form) {
    const gates = { pulse: 38, mortar: 100, cryo: 70, blaze: 80, tesla: 90, rail: 120 };
    if (!this.gate(`shoot-${form}`, gates[form] || 60)) return;
    switch (form) {
      case 'pulse':
        this.tone(980, 0.05, { type: 'triangle', volume: 0.022, slideTo: 1500 });
        break;
      case 'mortar':
        this.tone(120, 0.18, { type: 'sine', volume: 0.1, slideTo: 48 });
        this.noise(0.16, { volume: 0.055, type: 'lowpass', frequency: 700 });
        break;
      case 'cryo':
        this.tone(1500, 0.09, { type: 'sine', volume: 0.03, slideTo: 850 });
        this.noise(0.08, { volume: 0.02, type: 'highpass', frequency: 3200 });
        break;
      case 'blaze':
        this.noise(0.12, { volume: 0.028, type: 'bandpass', frequency: 900 });
        this.tone(180, 0.09, { type: 'sawtooth', volume: 0.012, slideTo: 120 });
        break;
      case 'tesla':
        this.tone(220, 0.1, { type: 'sawtooth', volume: 0.035, slideTo: 70 });
        this.noise(0.08, { volume: 0.03, type: 'highpass', frequency: 2500 });
        break;
      case 'rail':
        this.tone(95, 0.24, { type: 'sawtooth', volume: 0.07, slideTo: 34 });
        this.noise(0.22, { volume: 0.05, type: 'bandpass', frequency: 1800, slideTo: 300 });
        break;
      default:
        break;
    }
  }

  impact() {
    if (!this.gate('impact', 45)) return;
    this.noise(0.05, { volume: 0.018, type: 'highpass', frequency: 1800 });
  }

  death() {
    if (!this.gate('death', 45)) return;
    this.noise(0.12, { volume: 0.035, type: 'lowpass', frequency: 1400, slideTo: 300 });
    this.tone(260, 0.12, { type: 'square', volume: 0.02, slideTo: 90 });
  }

  bossDeath() {
    this.noise(0.8, { volume: 0.1, type: 'lowpass', frequency: 1200, slideTo: 80 });
    this.tone(80, 0.8, { type: 'sawtooth', volume: 0.08, slideTo: 30 });
    this.tone(180, 0.45, { type: 'square', volume: 0.04, slideTo: 45, delay: 0.1 });
  }

  leak() {
    this.tone(440, 0.16, { type: 'square', volume: 0.05 });
    this.tone(330, 0.24, { type: 'square', volume: 0.05, delay: 0.16 });
  }

  victory() {
    [261.6, 329.6, 392, 523.25, 659.25].forEach((f, i) =>
      this.tone(f, 0.5, { type: 'triangle', volume: 0.05, delay: i * 0.12 }),
    );
  }

  defeat() {
    [330, 277, 220, 165].forEach((f, i) =>
      this.tone(f, 0.4, { type: 'sawtooth', volume: 0.04, delay: i * 0.14 }),
    );
  }
}

