import { WORLD, TOWER_POS, TOWER_RADIUS, ... } from './config.js';
import { buildPath } from './path.js';
```

PATH_VERTS local? define in game or config. Put in game maybe config. I'll define in game:
```
const PATH_VERTS = [
 {x:-40,y:110}, {x:660,y:110}, {x:660,y:290}, {x:130,y:290}, {x:130,y:470}, {x:840,y:470}
];
```

Helper random, clamp, lerpAngle, dist, polygon.

Class Game:
constructor(canvas, { audio, onEvent }) {
  this.canvas; this.ctx = canvas.getContext('2d');
  this.audio; this.onEvent = onEvent||(()=>{});
  this.path = buildPath(...);
  this.path2D = this.makePath2D();
  this.bg = this.buildBackground();
  this.dpr = Math.min(window.devicePixelRatio||1, 2);
  this.canvas.width = WORLD.width * dpr; ...
  ctx.setTransform...
  this.time=0;
  this.mode='menu';
  this.paused=false;
  this.speed=1;
  this.seed = ...;
  this.resetAttract? Initialize arrays.
  this.raf...
  this.lastTs=performance.now();
  requestAnimationFrame(this.frame)
}
