() => {
  const n = window.__NEXUS__;
  const g = n.game;
  const cost = (lv) => {
    const costs = [60,100,160,240,360,520,740,1000,1350];
    return lv >= 10 ? null : costs[lv - 1];
  };
  const upgradeAll = () => {
    let guard = 0;
    while (g.level < 10 && guard++ < 20) {
      const c = cost(g.level);
      if (c == null || g.gold < c) break;
      g.upgrade();
    }
  };
  const play = (form) => {
    n.start();
    g.form = form;
    const log = [];
    for (let w = 1; w <= 20; w++) {
      if (g.mode !== 'prep') break;
      upgradeAll();
      g.startWave();
      let t = 0;
      while (g.mode === 'wave' && t < 150) {
        g.advance(2);
        t += 2;
        upgradeAll();
      }
      log.push({ w, mode: g.mode, lives: g.lives, level: g.level, gold: g.gold, score: Math.round(g.score), t });
      if (g.mode === 'victory' || g.mode === 'gameover') break;
    }
    return { form, mode: g.mode, wave: g.wave, lives: g.lives, level: g.level, score: Math.round(g.score), log };
  };
  return play('pulse');
}
EOF
